/* Export ONLY the LV2 entry point.
 *
 * mod-host loads every plugin into a single process. This fork and the store's
 * NAM share the same code, so the same C++ symbol names: without this script
 * the first one loaded wins for both, and the audio server goes down.
 */
{
    global:
        lv2_descriptor;
    local:
        *;
};
